@lru_cache(None)
def solve(covered, counts):
 global nodes
 nodes+=1
 if covered==full:
  return ((),) if not any(counts) else ()
 # area feasibility
 remain=66-covered.bit_count()
 if sum(n*(shlist[i][0]*shlist[i][1]) for i,n in enumerate(counts))!=remain: return ()
 best_opts=None
 for p in target:
  bit=1<<idx[p]
